
import json, base64, urllib.request, urllib.parse, time, sys

TOKEN   = "skbUvbYYIvf0Uwc43kqoHa7MX556BIABP7tNDQjW06yeBHY9ImiPeEjgMs87ZxlUafA5XRt6LXwn8d5Y9JcmDaZN13fvjxt6Tm3QgSAE8LqSvP6oU7zgF3W4dGb3jnjVIuBnZTICBsln2LHqgKjFIAybBohK6JCJWR8qHmP6CMhPVpsiPB79"
PROJECT = "vbnsqnkg"
BASE    = f"https://{PROJECT}.api.sanity.io/v2024-01-01/data"

def sanity_query(query):
    url = f"{BASE}/query/production?query={urllib.parse.quote(query)}"
    req = urllib.request.Request(url, headers={"Authorization": f"Bearer {TOKEN}"})
    with urllib.request.urlopen(req) as r:
        return json.loads(r.read())["result"]

def sanity_mutate(mutations):
    body = json.dumps({"mutations": mutations}).encode()
    req = urllib.request.Request(f"{BASE}/mutate/production", data=body, method="POST",
          headers={"Authorization": f"Bearer {TOKEN}", "Content-Type": "application/json"})
    with urllib.request.urlopen(req) as r:
        return json.loads(r.read())

# Load templates from embedded JSON
TEMPLATES_B64 = ""
templates = json.loads(base64.b64decode(TEMPLATES_B64).decode())
print(f"Loaded {len(templates)} templates")

created = updated = 0
errors = []

for tmpl in templates:
    try:
        existing = sanity_query(f'''*[_type == "outreachTemplate" && name == {json.dumps(tmpl["name"])}][0]._id''')
        doc = {
            "_type": "outreachTemplate",
            "name": tmpl["name"],
            "type": tmpl["type"],
            "subject": tmpl["subject"],
            "previewText": tmpl.get("previewText",""),
            "body": tmpl["body"],
            "variables": tmpl.get("variables",[]),
            "isActive": True,
        }
        if existing:
            result = sanity_mutate([{"patch": {"id": existing, "set": doc}}])
            updated += 1
            print(f"  UPDATED: {tmpl['name'][:60]}")
        else:
            import hashlib
            doc_id = "template-" + hashlib.md5(tmpl["name"].encode()).hexdigest()[:16]
            doc["_id"] = doc_id
            result = sanity_mutate([{"createOrReplace": doc}])
            created += 1
            print(f"  CREATED: {tmpl['name'][:60]}")
        time.sleep(0.2)
    except Exception as e:
        errors.append(f"{tmpl['name']}: {e}")
        print(f"  ERROR: {tmpl['name']}: {e}")

print(f"\nDone: {created} created, {updated} updated, {len(errors)} errors")
if errors:
    for e in errors:
        print(f"  ERROR: {e}")
    sys.exit(1)
